import math

def dijkstra(adj, nodes, start):
    dist = {n: math.inf for n in nodes}
    parent = {}
    done = set()
    dist[start] = 0

    while len(done) < len(nodes):
        # Cheapest unfinalised node. A real implementation uses heapq
        # here; this scan is O(V) and easier to read.
        current = None
        best = math.inf
        for node, d in dist.items():
            if node not in done and d < best:
                best = d
                current = node

        if current is None:
            break  # rest of the graph is unreachable
        done.add(current)

        for to, weight in adj.get(current, []):
            if to in done:
                continue
            candidate = best + weight
            if candidate < dist[to]:
                dist[to] = candidate   # relax the edge
                parent[to] = current

    return dist, parent

#include <limits>
#include <map>
#include <set>
#include <string>
#include <vector>

struct Edge { std::string to; int weight; };

std::map<std::string, double> dijkstra(
    const std::map<std::string, std::vector<Edge>>& adj,
    const std::vector<std::string>& nodes,
    const std::string& start,
    std::map<std::string, std::string>& parent) {
    const double INF = std::numeric_limits<double>::infinity();

    std::map<std::string, double> dist;
    for (const std::string& n : nodes) dist[n] = INF;
    std::set<std::string> done;
    dist[start] = 0;

    while (done.size() < nodes.size()) {
        // Cheapest unfinalised node. A real implementation uses a
        // priority_queue here; this scan is O(V) and easier to read.
        std::string current;
        bool found = false;
        double best = INF;
        for (const auto& [node, d] : dist) {
            if (!done.count(node) && d < best) {
                best = d;
                current = node;
                found = true;
            }
        }

        if (!found) break;  // rest of the graph is unreachable
        done.insert(current);

        auto it = adj.find(current);
        if (it == adj.end()) continue;

        for (const Edge& e : it->second) {
            if (done.count(e.to)) continue;
            double candidate = best + e.weight;
            if (candidate < dist[e.to]) {
                dist[e.to] = candidate;   // relax the edge
                parent[e.to] = current;
            }
        }
    }

    return dist;
}
